import json, re

with open('batches/batch_0046.json', encoding='utf-8') as f:
    data = json.load(f)

def jp_ratio(s):
    if not s: return 0
    jp = sum(1 for c in s if ('぀' <= c <= 'ヿ') or ('一' <= c <= '鿿') or c in '、。「」・ー')
    return jp / max(len(s),1)

def try_repairs(s):
    candidates = {}
    attempts = [
        ('latin1->utf8', lambda x: x.encode('latin1', errors='ignore').decode('utf-8', errors='ignore')),
        ('cp1252->cp932', lambda x: x.encode('cp1252', errors='ignore').decode('cp932', errors='ignore')),
        ('latin1->cp932', lambda x: x.encode('latin1', errors='ignore').decode('cp932', errors='ignore')),
    ]
    for name, fn in attempts:
        try:
            r = fn(s)
            candidates[name] = r
        except Exception:
            pass
    return candidates

def is_suspect(s):
    if not s: return False
    markers = ['Ã','Â','ã','â','ð','þ','¤','©','¸','«','»','¬','�']
    return any(m in s for m in markers) or bool(re.search(r'[A-Za-z]{1,3}\[[A-Za-z]', s))

results = {}
for item in data:
    idx = item['idx']
    name = item['name']
    for field in ('title','desc','body'):
        s = item.get(field,'')
        if is_suspect(s):
            cands = try_repairs(s)
            best_name, best_val, best_score = 'orig', s, jp_ratio(s)
            for cname, cval in cands.items():
                score = jp_ratio(cval)
                if score > best_score:
                    best_score = score
                    best_name = cname
                    best_val = cval
            results.setdefault(idx, {})[field] = (best_name, best_score, best_val)

for idx, fields in results.items():
    print(f"--- idx {idx} ---")
    for field, (bn, sc, val) in fields.items():
        print(f"  {field}: {bn} score={sc:.2f}")
        print("   ", val[:200].replace(chr(10),' | '))
